MOD = 998244353

def fast_pow(x, y):
    if x == 1:
        return 1
    if y == 0:
        return 1
    p = fast_pow(x, y // 2) % MOD
    p = p * p % MOD
    if y % 2 == 1:
        p = p * x % MOD
    return p

def obrat2():
    return fast_pow(2, MOD - 2)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    l = int(input_data[2])
    r = int(input_data[3])
    total = (r - l + 1)
    if n % 2 != 0 and m % 2 != 0:
        print(fast_pow(total, n * m))
    else:
        res1 = fast_pow(total, n * m - 1)
        if total % 2 == 0:
            res = res1 * (total // 2) % MOD
        else:
            res = (res1 * ((total + 1) // 2) % MOD + MOD - ((res1 + MOD - 1) % MOD) * obrat2() % MOD) % MOD
        print(res)

if __name__ == "__main__":
    main()

